class Solution:
    def minCostPeaks(self, t: List[int]) -> int:
        n = len(t)
        cost = [0] * n
        for i in range(1, n - 1):
            cost[i] = max(0, max(t[i - 1], t[i + 1]) + 1 - t[i])
        if n % 2 == 1:
            # n - 2 candidates (odd count), (n - 1) // 2 peaks: only indices 1, 3, 5, ... fit
            return sum(cost[i] for i in range(1, n - 1, 2))
        # n - 2 candidates (even count), k = n // 2 - 1 peaks. The chosen indices are
        # 1, 3, ..., 2j - 1 followed by 2j + 2, 2j + 4, ..., n - 2, for some j in 0..k.
        k = n // 2 - 1
        even_suffix = [0] * (n + 2)
        for i in range(n - 2, 0, -1):
            even_suffix[i] = even_suffix[i + 1] + (cost[i] if i % 2 == 0 else 0)
        best = even_suffix[2]
        odd_prefix = 0
        for j in range(1, k + 1):
            odd_prefix += cost[2 * j - 1]
            best = min(best, odd_prefix + even_suffix[2 * j + 2])
        return best

